<?phpnamespace ADMIN\AdminBundle\Entity;use Doctrine\ORM\EntityRepository;
class ProcesoRepository extends EntityRepository
{        public function getByFilter($filter){                $sSql = "SELECT p FROM ADMINAdminBundle:Proceso p WHERE 1=1 ";                if(!empty($filter['txtNombre'])){            if($filter['txtNombre'] != ""){                $sSql .= " and upper(p.nombre) like upper( '%".$filter['txtNombre']   ."%' )";            }        }                if(!empty($filter["fDesde"])){            $sSql .= " and p.fechaIni >= to_date( '".$filter["fDesde"]."', 'DD/MM/YYYY HH24:MI:SS' )";        }                if(!empty($filter["fHasta"])){            $sSql .= " and p.fechaIni <= to_date( '".$filter["fHasta"]."', 'DD/MM/YYYY HH24:MI:SS' )";        }                $sSql .= " ORDER BY p.id DESC";                        $query = $this->getEntityManager()->createQuery( $sSql  );                return $query;    }            public function getParametros($filter){                $sSql = "SELECT p FROM ADMINAdminBundle:Parametro p WHERE 1=1 ";                if(!empty($filter['txtNombre'])){            if($filter['txtNombre'] != ""){                $sSql .= " and upper(p.nombre) like upper( '%".$filter['txtNombre']   ."%' )";            }        }                        $sSql .= " ORDER BY p.parametroid DESC";        $query = $this->getEntityManager()->createQuery( $sSql  );                return $query;    }            public function updateParametro($parameters){        $sSql = "";        $oRes = false;                $prm = $parameters;        if( empty( $prm['id'] ) ){            $prm['id'] = 0;        }                if( empty( $prm['valornum'] ) ){            $prm['valornum'] = null;        }                if( empty( $prm['valorchar'] ) ){            $prm['valorchar'] = '';        }                $sSql .= "UPDATE ADMINAdminBundle:Parametro prm SET ";        $sSql .= "prm.valornum = " . ( $prm["valornum"] == '' ? "null" : "'".$prm["valornum"]."'" ) .", " ;        $sSql .= "prm.valorchar = " . ( $prm["valorchar"] == '' ? "null" : "'".$prm["valorchar"]."'" ) ." " ;        $sSql .= "WHERE prm.parametroid = " . $prm["id"]." ";        try{            $query = $this->getEntityManager()->createQuery( $sSql  );            $oRes = $query->getResult();        }        catch(Exception $ex){                    }                return $oRes;    }        }?>